<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import { useRouter } from 'vue-router'
import { Reading, FolderOpened, Star, Document, Search } from '@element-plus/icons-vue'
import type { SearchMode } from '@/types/classic'

const SEARCH_MODE_STORAGE_KEY = 'classic-search-mode'
const SEARCH_MODES: SearchMode[] = ['keyword', 'ai_enhanced', 'semantic']

function loadStoredSearchMode(): SearchMode {
  try {
    const stored = sessionStorage.getItem(SEARCH_MODE_STORAGE_KEY)
    if (stored && SEARCH_MODES.includes(stored as SearchMode)) return stored as SearchMode
  } catch {
    /* sessionStorage 不可用时忽略 */
  }
  return 'keyword'
}

const SEARCH_MODE_CONFIG: Record<SearchMode, { placeholder: string; examples: string[] }> = {
  keyword: {
    placeholder: '输入作者、朝代、名句等关键词',
    examples: ['杜甫', '唐', '明月', '离别'],
  },
  ai_enhanced: {
    placeholder: '用自然语言描述你想找的句子',
    examples: ['描写月亮的诗句', '推荐杜甫关于理想信念的五句诗'],
  },
  semantic: {
    placeholder: '输入一句话或概念，找语义相近的句子',
    examples: ['时光易逝', '壮志未酬', '思乡之情'],
  },
}

const router = useRouter()
const query = ref('')
const searchMode = ref<SearchMode>(loadStoredSearchMode())

// 保持下拉框选择：写入 sessionStorage，下次进入本页时恢复
watch(
  searchMode,
  (mode) => {
    try {
      sessionStorage.setItem(SEARCH_MODE_STORAGE_KEY, mode)
    } catch {
      /* sessionStorage 不可用时忽略 */
    }
  },
  { immediate: true }
)

const searchPlaceholder = computed(() => SEARCH_MODE_CONFIG[searchMode.value].placeholder)
const searchExamples = computed(() => SEARCH_MODE_CONFIG[searchMode.value].examples)

function goSearch() {
  const q = query.value?.trim()
  if (!q) return
  router.push({ path: '/classic/search', query: { q, mode: searchMode.value } })
}
</script>

